                .path("customerOrders.pageInfo.hasNextPage").entity(Boolean.class).isEqualTo(true)
                .path("customerOrders.pageInfo.endCursor").hasValue();

        verify(orders).findByCustomerId(1L, ScrollPosition.keyset(), Limit.of(10), Sort.by("id"));
    }

    @Test
    void customerOrdersContinuesFromTheCursorItWasGiven() {
        given(customers.existsById(2L)).willReturn(true);
        given(orders.findByCustomerId(eq(2L), any(), any(), any()))
                .willReturn(keysetWindow(List.of(order(2L, 2L), order(5L, 2L)), true))
