        verify(orders, times(2)).findByCustomerId(eq(2L), positions.capture(), eq(Limit.of(2)), eq(Sort.by("id")));
        KeysetScrollPosition resumed = (KeysetScrollPosition) positions.getAllValues().get(1);
        assertThat(resumed.getKeys()).containsKey("id");
        assertThat(((Number) resumed.getKeys().get("id")).longValue()).isEqualTo(5L);
    }

    @Test
